/* Reset de estilos básicos */ * { margin: 0; padding: 0; box-sizing: border-box; } /* Estilo general del cuerpo */ body { font-family: 'Arial', sans-serif; line-height: 1.6; background-color: #f4f4f9; color: #333; padding: 10px; } /* Estilo para el encabezado */ header { background-color: #2c3e50; color: #fff; padding: 20px 0; text-align: center; } header h1 { font-size: 2.5rem; margin-bottom: 10px; } header p { font-size: 1rem; font-style: italic; } /* Navegación */ nav { background-color: #34495e; display: flex; justify-content: center; padding: 10px 0; } nav a { color: #fff; text-decoration: none; margin: 0 15px; font-weight: bold; } nav a:hover { color: #f39c12; } /* Estilo para secciones */ section { margin: 20px 0; } section h2 { color: #2c3e50; font-size: 2rem; margin-bottom: 10px; border-bottom: 2px solid #f39c12; display: inline-block; } section p { font-size: 1rem; margin-bottom: 15px; } /* Botones */ button { background-color: #f39c12; color: #fff; border: none; padding: 10px 20px; cursor: pointer; border-radius: 5px; font-size: 1rem; } button:hover { background-color: #d35400; } /* Pie de página */ footer { background-color: #2c3e50; color: #fff; text-align: center; padding: 10px 0; margin-top: 20px; } footer p { font-size: 0.9rem; } /* Estilo responsivo */ @media (max-width: 768px) { header h1 { font-size: 2rem; } nav a { font-size: 0.9rem; margin: 0 10px; } section h2 { font-size: 1.5rem; } button { font-size: 0.9rem; padding: 8px 16px; } }
